mapper.select:
SELECT op.personnel_id personnelId, uu.name, uo.org_name department, d.name position, o.create_time applyTime, o.destination, o.start_time startTime, o.end_time endTime, ouc.name contact, ouc.tel link FROM outgoing_personnel op LEFT JOIN outgoing o ON o.out_id = op.out_id LEFT JOIN outgoing_unit_contact ouc ON ouc.out_id = o.out_id LEFT JOIN u_user uu ON uu.user_id = op.user_id LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = uosr.org_id AND uo.status_cd = '0' LEFT JOIN t_dict d ON d.status_cd = uosr.rel_cd AND (d.table_name = 'u_org_staff_rel' OR d.table_name = 's_store_user') AND d.table_columns = 'rel_cd' WHERE o.status_cd = '0' AND uu.status_cd = '0'
AND uu.name LIKE CONCAT('%',#{name},'%')
AND uo.org_name LIKE CONCAT('%',#{department},'%')
AND d.name LIKE CONCAT('%',#{position},'%')
AND o.create_time >= #{startDate}
AND o.create_time <= #{endDate}
ORDER BY o.create_time DESC
LIMIT #{page}, #{row}

SELECT COUNT(*) count FROM outgoing_personnel op LEFT JOIN outgoing o ON o.out_id = op.out_id LEFT JOIN outgoing_unit_contact ouc ON ouc.out_id = o.out_id LEFT JOIN u_user uu ON uu.user_id = op.user_id LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0' LEFT JOIN u_org uo ON uo.org_id = uosr.org_id AND uo.status_cd = '0' LEFT JOIN t_dict d ON d.status_cd = uosr.rel_cd AND (d.table_name = 'u_org_staff_rel' OR d.table_name = 's_store_user') AND d.table_columns = 'rel_cd' WHERE o.status_cd = '0' AND uu.status_cd = '0'
AND uu.name LIKE CONCAT('%',#{name},'%')
AND uo.org_name LIKE CONCAT('%',#{department},'%')
AND d.name LIKE CONCAT('%',#{position},'%')
AND o.create_time >= #{startDate}
AND o.create_time <= #{endDate}

SELECT o.out_id outId, o.start_time startTime, o.end_time endTime, o.destination, o.matter_detail matterDetail,
       uu.user_id userId, uu.`name`, uo.org_name department, o.state
FROM outgoing o
LEFT JOIN outgoing_personnel op ON op.out_id = o.out_id AND op.status_cd = '0'
LEFT JOIN u_user uu ON uu.user_id = op.user_id AND uu.status_cd = '0'
LEFT JOIN u_org_staff_rel uosr ON uosr.staff_id = uu.user_id AND uosr.status_cd = '0'
LEFT JOIN u_org uo ON uo.org_id = uosr.org_id AND uo.status_cd = '0'
WHERE o.status_cd = '0'
AND o.out_id IN (
    SELECT temp.outId
    FROM (
        SELECT out_id outId
        FROM outgoing


                state = #{state}


                and community_id = #{communityId}


                and user_id = #{userId}


        ORDER BY create_time DESC

            LIMIT #{page}, #{row}

    ) AS temp
)

SELECT out_id outId, uu.`name` userName, CONCAT(uo.org_name,d.`name`) departPosition, uu.tel, t.destination, t.start_time startTime, t.end_time endTime, t.matter_detail matterDetail FROM outgoing t LEFT JOIN u_user uu ON t.user_id = uu.user_id LEFT JOIN u_org_staff_rel r ON r.staff_id = uu.user_id LEFT JOIN u_org uo ON uo.org_id = r.org_id LEFT JOIN t_dict d ON d.status_cd = r.rel_cd AND (d.table_name = 'u_org_staff_rel' OR d.table_name = 's_store_user') AND d.table_columns = 'rel_cd' WHERE t.status_cd = '0' AND uu.status_cd = '0' AND r.status_cd = '0' AND uo.status_cd = '0'
and t.state = #{state}
and t.community_id= #{communityId}
and t.user_id = #{userId}
and t.out_id in
#{item}
order by t.create_time desc
limit #{page}, #{row}

